/* Exhaustive enumeration of all unrooted binary trees on n leaves, keeping the K trees of
 * smallest BME value  sum_{i<j} D_ij 2^(-tau_ij)  (tau_ij = number of edges between leaves
 * i and j).
 *
 *   enumerate_trees MATRIX K > top.txt
 *
 * MATRIX: first line n, then the n*n entries of D (row-major, whitespace separated).
 * Trees are generated by stepwise addition: start from the star on leaves 0, 1, 2 and
 * insert leaf k (k = 3..n-1) on each of the 2k-3 edges of the current tree, which visits
 * each of the (2n-5)!! trees exactly once. Values are computed in double precision; the
 * caller re-ranks the K trees in exact arithmetic, and K must be large enough that the
 * double-precision ranking cannot have dropped the true optimum (the caller checks the
 * margin between the best and the K-th value).
 *
 * Output: a line "trees <count>", then for each kept tree, best first, a line
 * "value <double>" followed by n lines of the path-length matrix. Progress (trees visited)
 * goes to stderr every PROGRESS trees.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 16
#define MAXNODES (2 * MAXN - 2)
#define PROGRESS 100000000ULL

static int n, K;
static double D[MAXN][MAXN];
static double pow2neg[MAXNODES + 1];
static int eu[2 * MAXN], ev[2 * MAXN], ne;
static unsigned long long visited;

typedef struct { double value; unsigned char tau[MAXN][MAXN]; } Kept;
static Kept *kept;   /* max-heap on value, size <= K */
static int nkept;

static void heap_push(const Kept *t) {
    int i;
    if (nkept < K) {
        i = nkept++;
    } else if (t->value < kept[0].value) {
        i = 0;   /* replace the root, then sift down */
        kept[0] = *t;
        for (;;) {
            int l = 2 * i + 1, r = l + 1, m = i;
            if (l < nkept && kept[l].value > kept[m].value) m = l;
            if (r < nkept && kept[r].value > kept[m].value) m = r;
            if (m == i) return;
            Kept tmp = kept[i]; kept[i] = kept[m]; kept[m] = tmp; i = m;
        }
    } else {
        return;
    }
    kept[i] = *t;   /* sift up */
    while (i > 0 && kept[(i - 1) / 2].value < kept[i].value) {
        Kept tmp = kept[i]; kept[i] = kept[(i - 1) / 2]; kept[(i - 1) / 2] = tmp;
        i = (i - 1) / 2;
    }
}

static void evaluate(void) {
    int adj[MAXNODES][3], deg[MAXNODES];
    int nodes = 2 * n - 2;
    memset(deg, 0, sizeof deg);
    for (int e = 0; e < ne; e++) {
        adj[eu[e]][deg[eu[e]]++] = ev[e];
        adj[ev[e]][deg[ev[e]]++] = eu[e];
    }
    Kept t;
    t.value = 0.0;
    for (int i = 0; i < n; i++) {
        int dist[MAXNODES], queue[MAXNODES], head = 0, tail = 0;
        for (int v = 0; v < nodes; v++) dist[v] = -1;
        dist[i] = 0; queue[tail++] = i;
        while (head < tail) {
            int v = queue[head++];
            for (int k = 0; k < deg[v]; k++) {
                int w = adj[v][k];
                if (dist[w] < 0) { dist[w] = dist[v] + 1; queue[tail++] = w; }
            }
        }
        t.tau[i][i] = 0;
        for (int j = 0; j < n; j++) {
            if (j == i) continue;
            t.tau[i][j] = (unsigned char)dist[j];
            if (j > i) t.value += D[i][j] * pow2neg[dist[j]];
        }
    }
    heap_push(&t);
    if (++visited % PROGRESS == 0) fprintf(stderr, "visited %llu trees\n", visited);
}

static void insert(int k) {
    if (k == n) { evaluate(); return; }
    int m = n + (k - 2);   /* the new internal node */
    int edges = ne;
    for (int e = 0; e < edges; e++) {
        int a = eu[e], b = ev[e];
        ev[e] = m;
        eu[ne] = m; ev[ne] = b;
        eu[ne + 1] = m; ev[ne + 1] = k;
        ne += 2;
        insert(k + 1);
        ne -= 2;
        ev[e] = b;
        (void)a;
    }
}

static int cmp_value(const void *x, const void *y) {
    double a = ((const Kept *)x)->value, b = ((const Kept *)y)->value;
    return (a > b) - (a < b);
}

int main(int argc, char **argv) {
    if (argc != 3) { fprintf(stderr, "usage: enumerate_trees MATRIX K\n"); return 2; }
    FILE *f = fopen(argv[1], "r");
    if (!f) { perror(argv[1]); return 1; }
    if (fscanf(f, "%d", &n) != 1 || n < 4 || n > MAXN) { fprintf(stderr, "bad n\n"); return 1; }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (fscanf(f, "%lf", &D[i][j]) != 1) { fprintf(stderr, "bad matrix\n"); return 1; }
    fclose(f);
    K = atoi(argv[2]);
    if (K < 1) { fprintf(stderr, "bad K\n"); return 1; }
    for (int d = 0; d <= MAXNODES; d++) pow2neg[d] = 1.0 / (double)(1ULL << d);
    kept = malloc(sizeof(Kept) * (size_t)K);
    if (!kept) { fprintf(stderr, "out of memory\n"); return 1; }
    /* the star on leaves 0, 1, 2 with centre n */
    ne = 0;
    for (int i = 0; i < 3; i++) { eu[ne] = i; ev[ne] = n; ne++; }
    insert(3);
    qsort(kept, (size_t)nkept, sizeof(Kept), cmp_value);
    printf("trees %llu\n", visited);
    for (int t = 0; t < nkept; t++) {
        printf("value %.17g\n", kept[t].value);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) printf("%d%c", kept[t].tau[i][j], j + 1 < n ? ' ' : '\n');
        }
    }
    return 0;
}
